'en', 'native_title_verified', NULL, NULL, NULL, NULL, NULL, 0, 'Applied Sciences', NULL, '11', '9', NULL, NULL, NULL, 'MDPI AG', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '10.3390/app11093942', NULL, NULL, NULL, '2076-3417', 'https://doi.org/10.3390/app11093942', NULL, NULL, NULL, 3, 'clinical', NULL, NULL, NULL, NULL, 'COMPLETE', 'VERIFIED', 'RESOLVED', NULL, NULL, 0, NULL, NULL, 'Expected the autism-specific quantified RT60 recommendation the 2026-08-20 antagonist and this project''s own May-2026 reasoning doc both attribute to it (0.4-0.7 s). Retrieval confirms EXISTENCE, journal, authors and year exactly. I have NOT read the full text, so the 0.4-0.7 s figure remains [UNVERIFIED-QUANT] here and is NOT written into any value column.', 'see search_executions exec 10-15 for this batch (verbatim, logged before screening)', NULL, ' || ADMITTED 2026-08-22 by PROMOTION from source_locators, ref_id REUSED not minted (recovered_from corpus-pre-reset-2026-08-06). SECOND WITNESS FOR OD-5: the R9 duplicate gate queries evidence_sources only and is blind to all 835 locator rows, so batch 1 searched the autism-acoustics question while the project already owned the most on-topic paper for it. R10 LADDER NOTE: the first Crossref call returned an EMPTY body with curl exit 35 (TLS), logged as e3b0c44298fc1c14.txt; rung-1 retry resolved. A publisher block is not a terminal answer and neither is a transient. [UNVERIFIED-QUANT]: the 0.4-0.7 s range attributed to this paper is NOT verified from full text here.', '2026-08-22 05:28', 'session_2026-08-22-research-batch-02-room-acoustic-performance', '2026-08-22', 'session_2026-08-22-research-batch-02-room-acoustic-performance', 'crossref', NULL, 1, NULL, '3942', 4, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'lower_control', 'pending', 'pending', NULL, NULL, NULL, NULL, NULL, 'tool', NULL);
INSERT INTO "evidence_sources" ("ref_id", "source_type", "author_count", "author_count_is_complete", "first_author_last", "first_author_first", "is_corporate_primary", "author_display", "pub_year", "pub_year_note", "pub_title", "pub_subtitle", "chapter_title", "original_title", "lang_detected", "lang_detection_method", "pub_title_en", "pub_subtitle_en", "chapter_title_en", "journal_name_en", "translation_method", "translation_reviewed", "journal_name", "journal_abbrev", "volume", "issue", "pages_start", "pages_end", "article_number", "publisher", "publisher_location", "edition", "book_title", "series", "series_number", "report_number", "institution", "standard_number", "doi", "pmid", "pmcid", "isbn", "issn", "url", "url_accessed", "handle", "local_id", "tier", "evidence_type", "jurisdiction", "co1_provenance", "co1_source_type", "synthesis_attribution_required", "metadata_quality", "verification_status", "doi_resolution_outcome", "bpc_shorthand", "bpc_note", "grey_flag", "grey_reason", "verification_note", "prior_expectation", "search_queries_used", "derivation_chain", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "verified_by_tool", "last_verified_at", "verification_attempt_count", "superseded_by_ref_id", "pages", "pub_month", "language", "subtype", "citation_count", "url_resolution_outcome", "url_last_fetched", "url_match_similarity", "metadata_integrity_status", "metadata_integrity_detail", "code_currency_status", "code_currency_verified_at", "code_currency_verified_by_session", "code_currency_notes", "scope", "data_capture_status", "citation_mining_status", "processing_blocked_reason", "standard_number_note", "author_display_note", "publisher_note", "verification_disposition", "verification_method", "verification_closure_reason") VALUES ('REF-00578', NULL, NULL, 0, 'Iglehart', NULL, 0, 'Iglehart F', 2016, NULL, 'Speech Perception in Classroom Acoustics by Children With Cochlear Implants and With Typical Hearing', NULL, NULL, NULL, 'en', 'native_title_verified', NULL, NULL, NULL, NULL, NULL, 0, 'American Journal of Audiology', NULL, '25', '2', '100', '109', NULL, 'American Speech Language Hearing Association', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '10.1044/2016_aja-15-0064', NULL, NULL, NULL, '1059-0889', 'https://doi.org/10.1044/2016_aja-15-0064', NULL, NULL, NULL, 1, 'clinical', NULL, NULL, NULL, NULL, 'COMPLETE', 'VERIFIED', 'RESOLVED', NULL, NULL, 0, NULL, NULL, 'Expected a Tier-1 controlled manipulation of RT with cochlear-implant children yielding a population-differentiated threshold. Abstract confirms exactly that: RTs of 0.3/0.6/0.9 s, and reduction to 0.3 s benefited CI children with no further benefit to typical-hearing peers - which is the mechanism a population-differentiated requirement needs. My prior was right in direction AND degree, which is rare here and worth recording as such.', 'see search_executions exec 10-15 for this batch (verbatim, logged before screening)', NULL, ' || ADMITTED 2026-08-22 by PROMOTION from source_locators, ref_id REUSED. FIRST WITNESS FOR OD-5 (named in GAP-B01-004). POPULATION CAUTION for R13: participants are CHILDREN with cochlear implants. DEAF carries ZERO item_population_links on room-acoustic-performance, so this Tier-1 source serves a population the item layer does not connect to this slug at all - the D-0165 taxonomy question, visible in the data rather than only in prose.', '2026-08-22 05:28', 'session_2026-08-22-research-batch-02-room-acoustic-performance', '2026-08-22', 'session_2026-08-22-research-batch-02-room-acoustic-performance', 'crossref', NULL, 1, NULL, '100-109', 6, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'high_control', 'pending', 'pending', NULL, NULL, NULL, NULL, NULL, 'tool', NULL);
INSERT INTO "evidence_sources" ("ref_id", "source_type", "author_count", "author_count_is_complete", "first_author_last", "first_author_first", "is_corporate_primary", "author_display", "pub_year", "pub_year_note", "pub_title", "pub_subtitle", "chapter_title", "original_title", "lang_detected", "lang_detection_method", "pub_title_en", "pub_subtitle_en", "chapter_title_en", "journal_name_en", "translation_method", "translation_reviewed", "journal_name", "journal_abbrev", "volume", "issue", "pages_start", "pages_end", "article_number", "publisher", "publisher_location", "edition", "book_title", "series", "series_number", "report_number", "institution", "standard_number", "doi", "pmid", "pmcid", "isbn", "issn", "url", "url_accessed", "handle", "local_id", "tier", "evidence_type", "jurisdiction", "co1_provenance", "co1_source_type", "synthesis_attribution_required", "metadata_quality", "verification_status", "doi_resolution_outcome", "bpc_shorthand", "bpc_note", "grey_flag", "grey_reason", "verification_note", "prior_expectation", "search_queries_used", "derivation_chain", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "verified_by_tool", "last_verified_at", "verification_attempt_count", "superseded_by_ref_id", "pages", "pub_month", "language", "subtype", "citation_count", "url_resolution_outcome", "url_last_fetched", "url_match_similarity", "metadata_integrity_status", "metadata_integrity_detail", "code_currency_status", "code_currency_verified_at", "code_currency_verified_by_session", "code_currency_notes", "scope", "data_capture_status", "citation_mining_status", "processing_blocked_reason", "standard_number_note", "author_display_note", "publisher_note", "verification_disposition", "verification_method", "verification_closure_reason") VALUES ('REF-00969', NULL, NULL, 0, 'Rosas-Pérez', NULL, 0, 'Rosas-Pérez C; Galbrun L; Stewart M; Payne S', 2023, NULL, 'How can anyone learn or teach? Experiences of autistic people with sound in schools and universities', NULL, NULL, NULL, 'en', 'native_title_verified', NULL, NULL, NULL, NULL, NULL, 0, 'Proceedings of Meetings on Acoustics', NULL, '51', NULL, NULL, NULL, NULL, 'ASA', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '10.1121/2.0001741', NULL, NULL, NULL, '1939-800X', 'https://doi.org/10.1121/2.0001741', NULL, NULL, NULL, 3, 'clinical', NULL, NULL, NULL, NULL, 'COMPLETE', 'VERIFIED', 'RESOLVED', NULL, NULL, 0, NULL, NULL, 'Expected an on-item companion to REF-00965: same team, same 12-adult cohort, but set in SCHOOLS AND UNIVERSITIES rather than daily life, which is what makes it on-item for a learning-space parameter. Confirmed. It does not weaken the L3 independence problem the 2026-08-20 pass raised - it SHARPENS it, because admitting it makes two of the AUT-side sources one cohort.', 'see search_executions exec 10-15 for this batch (verbatim, logged before screening)', NULL, ' || ADMITTED 2026-08-22, ref_id MINTED above the source_locators high-water mark (REF-00964). Named by workplan/2026-08-20-adversarial-adjudication-a18-aut.md section 8 item 4 as sitting unadmitted in REF-00965''s own reference list. L3 INDEPENDENCE LIMIT, inherited and worsened: same team and same 12-adult cohort as REF-00965, so the two are ONE line of testimony, not two, and any finding resting on their agreement must be read as one lineage. TIER DELIBERATELY CONSERVATIVE: graded clinical/lower_control -> T3 rather than co1 -> T1, even though its sibling REF-00965 currently carries co1/T1, because OD-D disputes exactly whether that lineage has a visible co-production warrant. Taking the lower grade avoids compounding a disputed claim; if OD-D sustains Co-1 for this lineage, re-grade this row UP in the same act.', '2026-08-22 05:28', 'session_2026-08-22-research-batch-02-room-acoustic-performance', '2026-08-22', 'session_2026-08-22-research-batch-02-room-acoustic-performance', 'crossref', NULL, 1, NULL, '015001', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'lower_control', 'pending', 'pending', NULL, NULL, NULL, NULL, NULL, 'tool', NULL);
