INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding") VALUES (10, 'room-acoustic-performance', NULL, 'EN', 1, 'co1', 'intrinsic', 'lived experience of people with dementia in care home acoustic environment reverberation noise participatory qualitative', '["TERM-007","TERM-030"]', 'consensus', 'scoping', NULL, 20, 10, 1, NULL, '["REF-00970"]', NULL, 0, 'session_2026-08-22-research-batch-02-room-acoustic-performance', '2026-08-22 05:22', 'R1 Co-1 pass, population DEM. Deliberately re-runs the frame of exec 2, which returned 20 and admitted 0 and whose null was recorded as a property of the literature (retracted; GAP-B01-002). The difference is query SHAPE: exec 2 carried no room-acoustic term at all. This one pairs the acoustic parameter with the population and the setting. Non-trivial on-parameter yield, so the earlier null was query-shape failure (R14), NOT absence.', 0);
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding") VALUES (11, 'room-acoustic-performance', NULL, 'EN', 1, 'co1', 'intrinsic', 'lived experience of mental health inpatients psychiatric ward noise acoustic environment qualitative service user perspective', '["TERM-007","TERM-049"]', 'consensus', 'scoping', NULL, 20, 10, 0, NULL, '[]', NULL, 0, 'session_2026-08-22-research-batch-02-room-acoustic-performance', '2026-08-22 05:22', 'R1 Co-1 pass, population MH. FIRST SEARCH EVER RUN FOR MH ON THIS SLUG: GAP-B01-003 records that MH (5 of 13 items) was never searched, never deferred and never mentioned by batch 1 - a larger unrecorded hole than the SCI absence that WAS elaborately recorded. Non-trivial yield including service-user interview studies and measured ward RT60 values, so the silence was coverage failure, not absence.', 0);
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding") VALUES (12, 'room-acoustic-performance', NULL, 'EN', 1, 'co1', 'intrinsic', 'acquired brain injury concussion noise sensitivity hyperacusis built environment lived experience rehabilitation acoustic', '["TERM-049"]', 'consensus', 'scoping', NULL, 20, 10, 0, NULL, '[]', NULL, 0, 'session_2026-08-22-research-batch-02-room-acoustic-performance', '2026-08-22 05:23', 'R1 Co-1 pass, population BRAIN. First search where BRAIN is the SUBJECT rather than a conjunct inside someone else query (GAP-B01-003). Rich yield on the POPULATION - IPA and interview studies of noise sensitivity after TBI/ABI, prevalence up to 83 percent - but a SCOPE LIMIT worth recording as the actual finding: not one retrieved item carries a room-acoustic parameter. They measure sensitivity as a SYMPTOM, not RT60/NRC/STC/NC as a room property. So BRAIN is well evidenced for acoustic VULNERABILITY and unevidenced for acoustic PERFORMANCE, which are different claims. Admitting any of these against a room-acoustic item would repeat the REF-00967 error the 2026-08-20 pass caught: a source with no value for the parameter anchoring a cell about that parameter.', 0);
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding") VALUES (13, 'room-acoustic-performance', NULL, 'EN', 1, 'clinical', 'high_control', 'reverberation time RT60 classroom learning space autistic neurodivergent special educational needs acoustic requirements', '["TERM-007"]', 'consensus', 'scoping', NULL, 20, 10, 1, NULL, '["REF-00969"]', NULL, 0, 'session_2026-08-22-research-batch-02-room-acoustic-performance', '2026-08-22 05:23', 'THE CORRECTED FRAME, prescribed by workplan/2026-08-20-adversarial-adjudication-a18-aut.md section 8 item 1. It pairs the acoustic PARAMETER with the SETTING and the POPULATION - the three-way cross that not one of batch 1 nine searches made. Batch 1 core claim, that no numeric value is authorable for A-18 x AUT, is REFUTED by retrieval, not by argument: the yield includes an A-B-A single-case study explicitly testing RT = 0.4 s Tmf with ASD children (RT modulated 1.1 to 0.39), measured RT/C50/STI in classrooms built for autistic pupils across two countries, a special-needs classroom field study, and a 50-country survey of national classroom targets giving 0.6-0.7 s and 35 dBA. Also surfaces 10.1121/2.0001741 (Rosas-Perez 2023), which the adjudication flagged as sitting UNADMITTED in REF-00965 own reference list. R14: the earlier null was a batch-frame query-shape failure, and no row in search_executions could express it because every individual query was well formed.', 0);
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding") VALUES (14, 'room-acoustic-performance', NULL, 'EN', 1, 'clinical', 'high_control', 'reverberation time classroom speech recognition children hearing aids cochlear implants threshold 0.3 seconds', '["TERM-007"]', 'consensus', 'scoping', NULL, 20, 10, 2, NULL, '["REF-00578", "REF-00325"]', NULL, 0, 'session_2026-08-22-research-batch-02-room-acoustic-performance', '2026-08-22 05:24', 'The population-differentiated RT threshold, searched directly for the first time. Returns BOTH held OD-5 leads as hits 1 and 2: Iglehart REF-00578 (CI children, RT 0.3/0.6/0.9 s) and Iglehart REF-00325 (hearing-aid children, same design) - the project already owned the strongest Tier-1 evidence on its own flagship parameter and could not see it, because the R9 duplicate gate queries evidence_sources only and is blind to all 835 source_locators rows (OD-5). R15 NOTE, AND MY OWN ERROR CORRECTED IN THE SAME ROW: I first wrote here that the reasoning doc calling this one Iglehart 2020 was wrong and that the record said 2019. That was an INFERENCE FROM THE DOI STRING (10.1044/2019_AJA-19-0010) plus a result listing, not from a payload. The retrieved Crossref payload says issued 2020, volume 29, issue 1, pages 6-17 - the DOI slug carries the assignment year, not the publication year. THE REASONING DOC WAS RIGHT AND I WAS WRONG. Caught and corrected BEFORE any admission was written, so no bibliographic field inherited it. Same failure class as the batch this session audits: a bibliographic claim written from something other than the bytes. NOTE FOR D-0165: every population in this yield is deaf or hard-of-hearing children, and DEAF carries ZERO item_population_links on this slug, so the strongest evidence for the parameter serves a population the item layer does not connect to it.', 0);
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding") VALUES (15, 'room-acoustic-performance', 'IT', 'IT', 5, 'national_fw', 'national', 'requisiti acustici aule scolastiche tempo di riverberazione UNI 11532 inclusione disabilità', '["TERM-007"]', 'consensus', 'scoping', NULL, 20, 10, 0, NULL, '[]', NULL, 0, 'session_2026-08-22-research-batch-02-room-acoustic-performance', '2026-08-22 05:24', 'R5 non-English pass, IT jurisdiction. QUERY-SHAPE CAVEAT, recorded so this is not miscounted as language coverage: the query was posed in Italian and the engine returned almost entirely ENGLISH-language records, because it matches semantically and does not honour a language constraint. So this row is evidence about UNI 11532-2 as a TOPIC, not about Italian-language literature, and the languages_searched counter must not treat it as an IT-language sweep. What it did surface on-topic: two D Orazio papers explaining UNI 11532-2:2020 through case studies, Astolfi 2019 on the standard itself (voluntary for private construction, MANDATORY for public procurement via the CAM decree), and Greenland 2019 on acoustic criteria for children with special, hearing and communication needs in mainstream classrooms - the SHCN framing the 2026-08-20 antagonist cited. A genuine IT-language sweep still owed.', 0);
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding") VALUES (16, 'room-acoustic-performance', NULL, 'EN', 3, 'clinical', 'lower_control', 'SELECT ref_id FROM source_locators WHERE lower(doi) IN (...) — R9 pre-check of five candidate DOIs against BOTH stores, by hand', '["TERM-007"]', 'source_locators', 'systematic', NULL, 5, 5, 1, NULL, '["REF-00561"]', NULL, 0, 'session_2026-08-22-research-batch-02-room-acoustic-performance', '2026-08-22 05:30', 'NOT a literature search - the internal stash lookup R9 cannot perform, logged as a retrieval act because that is what it was. Three of five candidate DOIs came back ALREADY HELD as source_locators leads (REF-00561, REF-00578, REF-00325, all recovered_from corpus-pre-reset-2026-08-06); two were unheld and were minted above the high-water mark REF-00964. REF-00561 did not appear in the top results of ANY of this batch six literature queries; it reached admission through this lookup, prompted by the 2026-08-20 adjudication. That is OD-5 demonstrated in miniature: the gate that is supposed to prevent duplication is blind to the store that holds the answer, and the only reason this batch found it is that a human-written adjudication said where to look.', 0);
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "session", "executed_at", "findings_note", "harm_finding") VALUES (17, 'room-acoustic-performance', NULL, 'EN', 1, 'clinical', 'high_control', 'Crossref reference-list retrieval for REF-00325 (10.1044/2019_AJA-19-0010), backward citation chase', '["TERM-007"]', 'crossref', 'systematic', 'backward', 44, 44, 0, NULL, NULL, NULL, 0, 'session_2026-08-22-research-batch-02-room-acoustic-performance', '2026-08-22 05:34', 'R2 backward mining from the strongest Tier-1 admission. 52 reference entries, 44 distinct. THIRD OD-5 DEMONSTRATION IN ONE BATCH: five of the cited DOIs are already held by this project, and FOUR are unconsumed source_locators leads invisible to the R9 gate - REF-00579, REF-00327, REF-00577 and REF-00576. The last two are Neuman 2010 and Wroblewski 2012, which references/bpc-reasoning/room-acoustic-performance.md names as Tier-1 anchors for the DEAF worst-case user. So the project holds at least SIX on-parameter Tier-1-candidate sources for this slug that no gate can see, and it found them only because a source it admitted happened to cite them. Staged as candidates, not admitted: R10 requires a re-retrieval ladder per locator and this batch is already at its scope ceiling.', 0);
INSERT INTO "search_admissions" ("exec_id", "ref_id", "created_at", "created_by_session") VALUES (10, 'REF-00970', '2026-08-22', 'session_2026-08-22-research-batch-02-room-acoustic-performance');
