INSERT INTO "search_admissions" ("exec_id", "ref_id", "created_at", "created_by_session") VALUES (16, 'REF-00561', '2026-08-22', 'session_2026-08-22-research-batch-02-room-acoustic-performance');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (31, 13, 'room-acoustic-performance', NULL, 'PENDING-VERIFICATION', 'Ghazanfar 2026 - Impact of classroom acoustic conditions on children with ASD (Urbanization, Sustainability and Society)', 'DOI not captured; retrieve via Crossref title search', 'UNVERIFIED', 1, 0, 'Not re-retrieved this batch; R10 forbids admission without running the re-retrieval ladder.', 'HYPOTHESIS (R15), highest-value lead in this batch: an A-B-A single-case design that explicitly TESTS RT = 0.4 s Tmf with ASD children, RT modulated 1.1 -> 0.39 s. If it holds on full text this is the first on-parameter, population-specific THRESHOLD TEST for AUT - precisely what batch 1 declared did not exist. n=4, so small. tier_guess 1 is a GUESS about design, not a grade. [UNVERIFIED-QUANT]', 'session_2026-08-22-research-batch-02-room-acoustic-performance', '2026-08-22');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (32, 13, 'room-acoustic-performance', NULL, 'PENDING-VERIFICATION', 'Caldas et al. 2023 - Measurements of classroom acoustic conditions in which young neurodiverse persons learn, Sao Paulo and Nebraska (JASA)', 'JASA 2023; DOI to retrieve', 'UNVERIFIED', 1, 0, 'Not re-retrieved this batch; R10 forbids admission without running the re-retrieval ladder.', 'HYPOTHESIS (R15): measured RT, C50, STI and S/N in rooms built for autistic pupils across two countries. On-parameter and on-population; unit of study is the ROOM, so a population match would cap at PARTIAL.', 'session_2026-08-22-research-batch-02-room-acoustic-performance', '2026-08-22');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (33, 13, 'room-acoustic-performance', NULL, 'PENDING-VERIFICATION', 'Ueno et al. 2019 - A field study on the acoustic environment of special-needs education classrooms (Building Acoustics)', 'Building Acoustics 2019', 'UNVERIFIED', 3, 0, 'Not re-retrieved this batch; R10 forbids admission without running the re-retrieval ladder.', 'HYPOTHESIS (R15): teacher survey plus observation in special-needs classrooms, and a constructed calming space of sound-absorbing material. Bears on A-16 sensory/quiet room provision as much as on RT60 - possible REHOME at resolution.', 'session_2026-08-22-research-batch-02-room-acoustic-performance', '2026-08-22');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (34, 13, 'room-acoustic-performance', NULL, 'PENDING-VERIFICATION', 'Tardini et al. 2025 - Survey of national target values on classroom acoustics (Building and Environment)', 'Building and Environment 2025', 'UNVERIFIED', 2, 0, 'Not re-retrieved this batch; R10 forbids admission without running the re-retrieval ladder.', 'HYPOTHESIS (R15): 50+ country survey reporting 0.6-0.7 s unoccupied RT and 35 dBA. Directly comparable to the 16-jurisdiction table in references/bpc-reasoning/room-acoustic-performance.md, which is Pass-1 with citation-grade verification PENDING - this could verify or refute a dozen of its cells at once. [UNVERIFIED-QUANT]', 'session_2026-08-22-research-batch-02-room-acoustic-performance', '2026-08-22');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (35, 10, 'room-acoustic-performance', NULL, 'PENDING-VERIFICATION', 'Talebzadeh et al. 2023 - Everyday acoustic environments and challenging behaviour in dementia: participatory observation in nursing homes (IJERPH)', 'IJERPH 2023', 'UNVERIFIED', 1, 0, 'Not re-retrieved this batch; R10 forbids admission without running the re-retrieval ladder.', 'HYPOTHESIS (R15): 24/7 participatory observation, 35 residents. Possible Co-1 CANDIDATE for DEM - participatory method is the same warrant OD-D is testing on the AUT side. Would be the first Co-1 the DEM population has on this slug. tier_guess 1 records the Co-1 hypothesis, not a grade.', 'session_2026-08-22-research-batch-02-room-acoustic-performance', '2026-08-22');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (36, 10, 'room-acoustic-performance', NULL, 'PENDING-VERIFICATION', 'Mu et al. 2021 - Acoustic environment of comprehensive activity spaces in nursing homes, Harbin (Applied Acoustics)', 'Applied Acoustics 2021', 'UNVERIFIED', 3, 0, 'Not re-retrieved this batch; R10 forbids admission without running the re-retrieval ladder.', 'HYPOTHESIS (R15): carries an on-parameter threshold for older adults - subjective comfort declined above RT 4 s or 65 dB(A). An order of magnitude looser than any classroom target, which is a finding about setting-dependence rather than a contradiction. [UNVERIFIED-QUANT]', 'session_2026-08-22-research-batch-02-room-acoustic-performance', '2026-08-22');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (37, 11, 'room-acoustic-performance', NULL, 'PENDING-VERIFICATION', 'Deng et al. 2023 - The acoustic environment in typical hospital wards in China (Applied Acoustics)', 'Applied Acoustics 2023', 'UNVERIFIED', 3, 0, 'Not re-retrieved this batch; R10 forbids admission without running the re-retrieval ladder.', 'HYPOTHESIS (R15): measured ward RT 0.34-0.67 s (500 Hz-1 kHz) and 24 h Leq 57.3-63.9 dBA. First on-parameter measurement retrieved for a health-care ward setting, relevant to MH and to clinical rooms this slug serves. [UNVERIFIED-QUANT]', 'session_2026-08-22-research-batch-02-room-acoustic-performance', '2026-08-22');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (38, 12, 'room-acoustic-performance', NULL, 'PENDING-VERIFICATION', 'Landon et al. 2012 - Hearing every footstep: noise sensitivity following traumatic brain injury (Neuropsychological Rehabilitation)', 'Neuropsych Rehab 2012', 'UNVERIFIED', 3, 0, 'Not re-retrieved this batch; R10 forbids admission without running the re-retrieval ladder.', 'HYPOTHESIS (R15): IPA with six people with TBI. Strong on POPULATION for BRAIN and carries NO room-acoustic parameter - staged rather than admitted precisely because admitting it against a room-acoustic item would repeat the REF-00967 error the 2026-08-20 pass caught.', 'session_2026-08-22-research-batch-02-room-acoustic-performance', '2026-08-22');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (39, 15, 'room-acoustic-performance', NULL, 'PENDING-VERIFICATION', 'D''Orazio et al. 2025 - The Italian standard on classroom acoustics UNI 11532-2:2020 explained through case studies (Applied Acoustics)', 'Applied Acoustics 2025', 'UNVERIFIED', 5, 0, 'Not re-retrieved this batch; R10 forbids admission without running the re-retrieval ladder.', 'HYPOTHESIS (R15): route to the actual UNI 11532-2:2020 clause values, which the reasoning doc lists as class A4 approx 0.5 s with verification PENDING. The STANDARD is the primary; this is the explainer, so R3 will need the clause, not this paper.', 'session_2026-08-22-research-batch-02-room-acoustic-performance', '2026-08-22');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (40, 14, 'room-acoustic-performance', NULL, 'PENDING-VERIFICATION', 'Kanigalpula et al. 2026 - Effects of age and reverberation on speech recognition in school-age children (Int J Pediatric Otorhinolaryngology)', 'IJPORL 2026', 'UNVERIFIED', 1, 0, 'Not re-retrieved this batch; R10 forbids admission without running the re-retrieval ladder.', 'HYPOTHESIS (R15): quantifies a TRADE-OFF rather than a threshold - 1.0 s of added RT costs about 8.17 dB SNR, each year of age confers about +1.79 dB. Measured classrooms averaged 2.47 s, roughly 5-6x recommended. Typical-hearing children, so PROXY at best for every population this slug serves. [UNVERIFIED-QUANT]', 'session_2026-08-22-research-batch-02-room-acoustic-performance', '2026-08-22');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (41, 17, 'room-acoustic-performance', NULL, 'PENDING-VERIFICATION', 'Neuman, Wroblewski, Hajicek & Rubinstein 2010 - Combined Effects of Noise and Reverberation on Speech Recognition Performance of Normal-Hearing Children and Adults (Ear and Hearing)', '10.1097/aud.0b013e3181d3d514', 'UNVERIFIED', 1, 0, 'Held as source_locators lead REF-00577. Not admitted: R10 requires the re-retrieval ladder per locator and DR 12.2 caps batch scope - a failed batch of 30 remediates far worse than one of 10.', 'HELD LEAD surfaced by backward mining from REF-00325; invisible to R9. references/bpc-reasoning/room-acoustic-performance.md names it a Tier-1 anchor for the DEAF worst-case user. HYPOTHESIS (R15): RT 0.3/0.6/0.8 s, 63 children and 9 adults, virtual classroom. Participants are TYPICAL-HEARING, so on-parameter but PROXY at best for every population this slug serves. [UNVERIFIED-QUANT]', 'session_2026-08-22-research-batch-02-room-acoustic-performance', '2026-08-22');
