INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "session", "created_at") VALUES (44, 17, 'room-acoustic-performance', NULL, 'PENDING-VERIFICATION', 'Finitzo-Hieber & Tillman 1978 - Room Acoustics Effects on Monosyllabic Word Discrimination Ability for Normal and Hearing-Impaired Children (Journal of Speech and Hearing Research)', '10.1044/jshr.2103.440', 'UNVERIFIED', 1, 0, 'Held as source_locators lead REF-00327. Not admitted: R10 requires the re-retrieval ladder per locator and DR 12.2 caps batch scope - a failed batch of 30 remediates far worse than one of 10.', 'HELD LEAD surfaced by backward mining; title and authors RESOLVED from a retrieved payload. HYPOTHESIS (R15): this is the FOUNDATIONAL room-acoustics-and-hearing-impaired-children paper, 1978, and the ancestor of the whole Iglehart line. The project has held it as an invisible lead since the 2026-08-06 reset while batch 1 reported the room-side Tier-1 evidence absent. If any single row makes the OD-5 case, it is this one.', 'session_2026-08-22-research-batch-02-room-acoustic-performance', '2026-08-22');
